    "Заголовки частин («1 куплет:», «Приспів:», «Брідж:», «Програш:») розпізнаються автоматично, текст ділиться на слайди.":"Les titres de section (\"Couplet 1 :\", \"Refrain :\", \"Pont :\") sont détectés automatiquement et le texte est découpé en diapositives.",
