    "Куплет 2":"Posmas 2","Куплет 3":"Posmas 3","Куплет 4":"Posmas 4","Завантажте кілька фонів один раз — далі обирайте їх для будь-якої теми.":"Vieną kartą importuokite kelis fonus — tada rinkitės juos bet kuriai temai.","Розмір посилання":"Nuorodos dydis","Заокруглення":"Kampų apvalinimas","Відступ з боків":"Šoninė paraštė","Видалити пісню":"Ištrinti giesmę","Імпортовано переклад":"Vertimas importuotas","1 куплет:\nПерший рядок...\nДругий рядок...\n\nПриспів:\n...":"Posmas 1:\nPirma eilutė...\nAntra eilutė...\n\nPriedainis:\n...","Розмір (pt)":"Dydis (pt)","Міжлітерний інтервал":"Tarpai tarp raidžių","Міжрядковий інтервал":"Tarpai tarp eilučių","Відступ між реченнями":"Tarpai tarp sakinių","Прозорість":"Nepermatomumas","Відступ":"Vidinė paraštė","Перехід між слайдами (наплив)":"Perėjimas tarp skaidrių (perliejimas)","OK":"OK",
